import express from 'express';
import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import pg, { type Pool as PgPool, type QueryResultRow } from 'pg';

const { Pool } = pg;

const inventoryItemsStatsSql = await readFile(
  new URL('./sql/inventory-items-stats.sql', import.meta.url),
  'utf8',
);

type Database = Pick<PgPool, 'query'>;

interface InventoryItemsStatsRow extends QueryResultRow {
  activeCount: string;
  totalQuantity: string;
  newestCreatedAt: Date | null;
}

export function createApp(database: Database) {
  const app = express();
  app.use(express.json());
  app.get('/health', (_request, response) => response.status(200).json({ status: 'ok' }));
  app.get('/inventory-items/stats', async (_request, response, next) => {
    try {
      const result = await database.query<InventoryItemsStatsRow>(inventoryItemsStatsSql);
      const stats = result.rows[0];

      response.status(200).json({
        activeCount: Number(stats.activeCount),
        totalQuantity: Number(stats.totalQuantity),
        newestCreatedAt: stats.newestCreatedAt?.toISOString() ?? null,
      });
    } catch (error) {
      next(error);
    }
  });
  return app;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const database = new Pool({ connectionString: process.env.DATABASE_URL });
  const app = createApp(database);
  app.listen(Number(process.env.PORT ?? 3000));
}
===== source/src/sql/inventory-items-stats.sql =====
SELECT
  COUNT(*) AS "activeCount",
  COALESCE(SUM(quantity), 0) AS "totalQuantity",
  MAX(created_at) AS "newestCreatedAt"
FROM inventory_items
WHERE is_active = TRUE;
===== source/database/schema/001_inventory.sql =====
CREATE TABLE inventory_items (
  id uuid PRIMARY KEY, sku text NOT NULL, quantity integer NOT NULL CHECK (quantity >= 0),
  is_active boolean NOT NULL, created_at timestamptz NOT NULL
);
CREATE TABLE inventory_reservations (
  request_id uuid PRIMARY KEY, inventory_item_id uuid NOT NULL REFERENCES inventory_items(id),
  quantity integer NOT NULL CHECK (quantity > 0), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE inventory_events (
  id bigserial PRIMARY KEY, request_id uuid NOT NULL, inventory_item_id uuid NOT NULL REFERENCES inventory_items(id),
  event_type text NOT NULL, quantity integer NOT NULL CHECK (quantity > 0), created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (request_id, event_type)
);
